// SPDX-License-Identifier: EPL-2.0
// `toString()` of the multimaps: the Guava Javadoc of `AbstractMultimap.toString()` says "Returns a string representation of the multimap,
// generated by calling toString on the map returned by Multimap.asMap()", i.e. `AbstractMap.toString` of key to collection:
// `{k1=[v1, v2], k2=[v3]}`, the keys in `keySet()` order and each key's values in that key's collection order (an empty multimap prints
// `{}`); a value or key is converted by `String.valueOf`. The compound JSON debug output prints the root graph's CROSS_HIERARCHY_MAP this
// way (`JsonDebugUtil.java:611`); the recorded text of that line is replayed in src/alg/layered/LayeredCompoundSites.test.ts.
// @see https://guava.dev/releases/33.3.0-jre/api/docs/com/google/common/collect/AbstractMultimap.html#toString()
import { describe, expect, it } from 'vitest';
import { STRING } from '../java/util/HashStrategy.js';
import { ArrayListMultimap } from './ArrayListMultimap.js';
import { HashMultimap } from './HashMultimap.js';
import { LinkedHashMultimap } from './LinkedHashMultimap.js';
import { LinkedListMultimap } from './LinkedListMultimap.js';
import type { Multimap } from './Multimap.js';
import { TreeMultimap } from './TreeMultimap.js';

const compare = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0);

/** Fills a multimap in the order b=1, a=2, b=3, a=4 plus c=5. */
function filled(map: Multimap<string, string>): Multimap<string, string> {
  [
    ['b', '1'],
    ['a', '2'],
    ['b', '3'],
    ['a', '4'],
    ['c', '5'],
  ].forEach(([k, v]) => map.put(k!, v!));
  return map;
}

describe('Multimap.toString (AbstractMultimap.toString: asMap().toString())', () => {
  it('prints an empty multimap as {}', () => {
    expect(String(LinkedHashMultimap.create(STRING, STRING))).toBe('{}');
    expect(String(HashMultimap.create(STRING, STRING))).toBe('{}');
  });

  it('prints keys in first-put order and each key values in put order for a linked multimap', () => {
    expect(String(filled(LinkedHashMultimap.create(STRING, STRING)))).toBe('{b=[1, 3], a=[2, 4], c=[5]}');
  });

  it('groups a list multimap by key in first-put order', () => {
    expect(String(filled(LinkedListMultimap.create(STRING, STRING)))).toBe('{b=[1, 3], a=[2, 4], c=[5]}');
    const single = ArrayListMultimap.create(STRING, STRING);
    single.put('a', '2');
    single.put('a', '4');
    expect(String(single)).toBe('{a=[2, 4]}');
  });

  it('prints a tree multimap in key order', () => {
    expect(String(filled(TreeMultimap.create(compare, compare)))).toBe('{a=[2, 4], b=[1, 3], c=[5]}');
  });

  it('prints the keys and values of a hash multimap in the order of the key table and the value sets', () => {
    const map = filled(HashMultimap.create(STRING, STRING));
    const entries = map.keySet().map((k) => `${k}=[${[...map.get(k)].join(', ')}]`);
    expect(String(map)).toBe(`{${entries.join(', ')}}`);
  });

  it('prints through String.valueOf: a value with its own toString uses it', () => {
    const map = LinkedHashMultimap.create<{ toString(): string }, { toString(): string }>(
      { hash: () => 1, equals: (a, b) => a === b },
      { hash: () => 1, equals: (a, b) => a === b },
    );
    map.put({ toString: () => 'K' }, { toString: () => 'OUT:V' });
    expect(String(map)).toBe('{K=[OUT:V]}');
  });
});
